import React, { useCallback, useRef, useState } from 'react';
import { HostEvent, RuntimeFilterOp } from '@thoughtspot/visual-embed-sdk';
import { LiveboardEmbed } from '@thoughtspot/visual-embed-sdk/react';
import {
  TOP_HEADER_PX,
  LIVEBOARD_NO_HEADER_CUSTOMIZATIONS,
} from '../config/thoughtspot';
import { useTier } from '../config/TierContext';
import { formatThoughtSpotEmbedError } from '../utils/thoughtspotErrors';
import FilterBar, { FilterDef, FilterSelection } from '../components/FilterBar';
import ParameterBar, { ParameterDef, ParameterSelection } from '../components/ParameterBar';

// ─── Constants ────────────────────────────────────────────────────────────────

const BG          = '#FFFFFF';
const LABEL       = 'rgba(0,0,0,0.45)';
const EMBED_MIN_H = `calc(100vh - ${TOP_HEADER_PX}px - 320px)`;

const SMYTHS_OVERVIEW_LIVEBOARD_ID = '5e3313c4-d293-4218-a9c5-af117f7c3015';

const TABS = [
  { id: 'tab1', label: 'Overview', tabId: '1c8444c3-2baf-4acc-8541-fcaca51a8e9f' },
  { id: 'tab2', label: 'Detail',   tabId: '00e30fcb-7f53-4619-84ab-b7a9e3a69272' },
];

// ─── Filter configuration ─────────────────────────────────────────────────────
// Column names match the ThoughtSpot model (Toy Store Demo Model) exactly.
// Option values reflect the actual data values in dim_products_toy / dim_stores_toy.
// Update option lists to match your real data if they differ.

const FILTERS_CONFIG: FilterDef[] = [
  {
    id: 'category',
    label: 'Category',
    columnName: 'Category',           // dim_products_toy::category
    options: [
      'Action Figures',
      'Arts & Crafts',
      'Baby & Toddler',
      'Board Games',
      'Construction',
      'Dolls & Accessories',
      'Electronic Toys',
      'Outdoor & Sports',
      'Puzzles',
      'Remote Control',
      'Role Play',
      'STEM & Learning',
      'Vehicles',
    ],
  },
  {
    id: 'brand',
    label: 'Brand',
    columnName: 'Brand',              // dim_products_toy::brand
    options: [
      'Barbie',
      'Fisher-Price',
      'Hasbro',
      'Hot Wheels',
      'LEGO',
      'Mattel',
      'Nerf',
      'Nintendo',
      'Playmobil',
      'Schleich',
      'VTech',
    ],
  },
  {
    id: 'age_range',
    label: 'Age Range',
    columnName: 'Age Range',          // dim_products_toy::age_range
    options: [
      '0-2',
      '3-5',
      '6-8',
      '9-11',
      '12+',
    ],
  },
  {
    id: 'region',
    label: 'Region',
    columnName: 'Region',             // dim_stores_toy::region
    options: [
      'East of England',
      'East Midlands',
      'London',
      'North East',
      'North West',
      'Northern Ireland',
      'Republic of Ireland',
      'Scotland',
      'South East',
      'South West',
      'Wales',
      'West Midlands',
      'Yorkshire',
    ],
  },
  {
    id: 'store_name',
    label: 'Store Name',
    columnName: 'Store Name',         // dim_stores_toy::store_name
    options: [
      'Brent Cross',
      'Croydon',
      'Birmingham',
      'Manchester Trafford',
      'Leeds',
      'Glasgow',
      'Edinburgh',
      'Cardiff',
      'Bristol',
      'Newcastle',
      'Dublin Blanchardstown',
      'Dublin Tallaght',
      'Cork',
      'Belfast',
    ],
  },
  {
    id: 'city',
    label: 'City',
    columnName: 'City',               // dim_stores_toy::city
    options: [
      'Belfast',
      'Birmingham',
      'Bristol',
      'Cardiff',
      'Cork',
      'Dublin',
      'Edinburgh',
      'Glasgow',
      'Leeds',
      'London',
      'Manchester',
      'Newcastle',
      'Sheffield',
    ],
  },
  {
    id: 'store_format',
    label: 'Store Format',
    columnName: 'Store Format',       // dim_stores_toy::store_format
    options: [
      'Superstore',
      'Standard',
      'Compact',
    ],
  },
];

// ─── Parameter configuration ──────────────────────────────────────────────────
// parameterName must match the ThoughtSpot parameter name exactly (case-sensitive).
// options.value must match the allowed values defined in ThoughtSpot.

// Values and defaults taken directly from the TML parameter definitions.
const PARAMETERS_CONFIG: ParameterDef[] = [
  {
    id: 'metric',
    label: 'Metric Picker',
    parameterName: 'Metric Picker',   // id: ca04ffe0-1f1c-4b36-9ee8-13c2cf0dc540
    defaultValue: 'Net Revenue',      // TML default_value
    options: [
      { label: 'Gross Revenue',       value: 'Gross Revenue' },
      { label: 'Net Revenue',         value: 'Net Revenue' },
      { label: 'Quantity Sold',       value: 'Quantity Sold' },
      { label: 'Discount Amount',     value: 'Discount Amount' },
      { label: 'Cost of Goods Sold',  value: 'Cost of Goods Sold' },
    ],
  },
  {
    id: 'dimension',
    label: 'Dimension Picker',
    parameterName: 'Dimension Picker', // id: 6a067879-3ff7-4645-bca0-215ddca13b82
    defaultValue: 'Category',          // TML default_value
    options: [
      { label: 'Product Name',  value: 'Product Name' },
      { label: 'Category',      value: 'Category' },
      { label: 'Brand',         value: 'Brand' },
      { label: 'Store Format',  value: 'Store Format' },
      { label: 'Region',        value: 'Region' },
      { label: 'Age Range',     value: 'Age Range' },
      { label: 'Store Name',    value: 'Store Name' },
      { label: 'City',          value: 'City' },
    ],
  },
];

// Build a ThoughtSpot runtimeFilters array from the selection state
function buildRuntimeFilters(
  config: FilterDef[],
  selection: FilterSelection
): { columnName: string; operator: RuntimeFilterOp; values: string[] }[] {
  return config
    .filter((f) => (selection[f.id] ?? []).length > 0)
    .map((f) => ({
      columnName: f.columnName,
      operator: RuntimeFilterOp.IN,
      values: selection[f.id],
    }));
}

// ─── Page ─────────────────────────────────────────────────────────────────────

export default function DashboardHome() {
  const { hiddenActions, disabledActions } = useTier();
  const [selectedTab, setSelectedTab]             = useState('tab1');
  const [filterSelection, setFilterSelection]     = useState<FilterSelection>({});
  const [parameterSelection, setParameterSelection] = useState<ParameterSelection>(
    // Initialise each parameter to its default value
    Object.fromEntries(PARAMETERS_CONFIG.map((p) => [p.id, p.defaultValue]))
  );
  const liveboardRef                              = useRef<any>(null);
  const active                                    = TABS.find((t) => t.id === selectedTab)!;

  const onError = useCallback(
    (err: { data?: { errorMessage?: string }; message?: string }) => {
      console.error('[ThoughtSpot Liveboard]', formatThoughtSpotEmbedError(err), err);
    },
    []
  );

  // Apply a single filter dimension change and push to ThoughtSpot
  const handleFilterChange = useCallback(
    (filterId: string, values: string[]) => {
      setFilterSelection((prev) => {
        const next = { ...prev, [filterId]: values };
        const runtimeFilters = buildRuntimeFilters(FILTERS_CONFIG, next);
        try {
          liveboardRef.current?.trigger(HostEvent.UpdateRuntimeFilters, {
            runtimeFilters,
          });
        } catch (e) {
          console.warn('[FilterBar] UpdateRuntimeFilters failed', e);
        }
        return next;
      });
    },
    []
  );

  // Clear all filters
  const handleClearAll = useCallback(() => {
    setFilterSelection({});
    try {
      liveboardRef.current?.trigger(HostEvent.UpdateRuntimeFilters, {
        runtimeFilters: [],
      });
    } catch (e) {
      console.warn('[FilterBar] ClearAll failed', e);
    }
  }, []);

  // Handle parameter selection — update state (embed key will change → clean remount)
  const handleParameterChange = useCallback(
    (parameterId: string, value: string) => {
      setParameterSelection((prev) => ({ ...prev, [parameterId]: value }));
    },
    []
  );

  // Reset all parameters back to their TML-defined defaults
  const handleParameterReset = useCallback(() => {
    setParameterSelection(
      Object.fromEntries(PARAMETERS_CONFIG.map((p) => [p.id, p.defaultValue]))
    );
  }, []);

  // Current runtime filters to pass as initial prop (used on tab remount)
  const currentRuntimeFilters = buildRuntimeFilters(FILTERS_CONFIG, filterSelection);

  // Current runtime parameters to pass as prop
  const currentRuntimeParameters = PARAMETERS_CONFIG.map((p) => ({
    name: p.parameterName,
    value: parameterSelection[p.id] ?? p.defaultValue,
  }));

  // Embed key: changes when tab OR parameters change → forces clean remount with new params
  const embedKey = `${active.tabId}__${currentRuntimeParameters.map((p) => `${p.name}:${p.value}`).join('|')}`;

  return (
    <div style={{ backgroundColor: BG, minHeight: `calc(100vh - ${TOP_HEADER_PX}px)` }}>

      {/* ── Page header ── */}
      <div style={{ padding: '1.75rem 2.5rem 1rem' }}>
        <div
          style={{
            fontSize: 10,
            fontWeight: 600,
            letterSpacing: '0.12em',
            textTransform: 'uppercase',
            color: LABEL,
            marginBottom: 6,
          }}
        >
          Smyths
        </div>
        <h1
          style={{
            fontSize: 26,
            fontWeight: 800,
            color: '#003D6B',
            margin: '0 0 1rem',
            letterSpacing: '-0.03em',
          }}
        >
          Retail Overview
        </h1>

        {/* Tab pill switcher */}
        <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
          {TABS.map((tab) => {
            const isActive = tab.id === selectedTab;
            return (
              <button
                key={tab.id}
                type="button"
                onClick={() => setSelectedTab(tab.id)}
                style={{
                  padding: '7px 20px',
                  borderRadius: 6,
                  border: `1px solid ${isActive ? '#009FE3' : 'rgba(0,0,0,0.15)'}`,
                  background: isActive ? '#009FE3' : '#FFFFFF',
                  color: isActive ? '#FFFFFF' : 'rgba(17,17,17,0.70)',
                  fontSize: 13.5,
                  fontWeight: isActive ? 600 : 400,
                  cursor: 'pointer',
                  transition: 'all 0.15s ease',
                  whiteSpace: 'nowrap',
                  letterSpacing: '-0.01em',
                }}
              >
                {tab.label}
              </button>
            );
          })}
        </div>
      </div>

      {/* ── Parameter bar ── */}
      <ParameterBar
        parameters={PARAMETERS_CONFIG}
        selected={parameterSelection}
        onSelectionChange={handleParameterChange}
      />

      {/* ── Filter bar ── */}
      <FilterBar
        filters={FILTERS_CONFIG}
        selected={filterSelection}
        onSelectionChange={handleFilterChange}
        onClearAll={handleClearAll}
      />

      {/* ── Liveboard embed ── */}
      <div style={{ padding: '0 2.5rem 2rem' }}>
        <div
          style={{
            backgroundColor: '#FFFFFF',
            borderRadius: 10,
            overflow: 'visible',
            minHeight: EMBED_MIN_H,
            border: '1px solid rgba(0,159,227,0.10)',
          }}
        >
          <LiveboardEmbed
            key={embedKey}
            ref={liveboardRef}
            liveboardId={SMYTHS_OVERVIEW_LIVEBOARD_ID}
            activeTabId={active.tabId}
            runtimeFilters={currentRuntimeFilters}
            runtimeParameters={currentRuntimeParameters}
            fullHeight
            hideTabPanel
            isLiveboardStylingAndGroupingEnabled
            hiddenActions={hiddenActions}
            disabledActions={disabledActions}
            customizations={LIVEBOARD_NO_HEADER_CUSTOMIZATIONS}
            onError={onError}
            style={{ width: '100%', minHeight: EMBED_MIN_H, display: 'block', border: 'none' }}
          />
        </div>
      </div>
    </div>
  );
}
